export function safeSourceUrl(value) {
    if (typeof value !== 'string' || !/^https:\/\//i.test(value)) return '';
    try {
        const url = new URL(value);
        return url.username || url.password || !url.hostname ? '' : url.href;
    } catch (_) { return ''; }
}

export function isWhisperEligible(fact) {
    return Boolean(fact?.eligible === true && fact.lane === 'whisper' && fact.reviewStatus === 'source_checked'
        && typeof fact.text === 'string' && fact.text.trim() && safeSourceUrl(fact.source?.url));
}

export const WHISPER_FACTS = Object.freeze(IMPORTED_FACTS.filter(isWhisperEligible));

export function publicFact(fact) {
    if (!isWhisperEligible(fact)) return null;
    return { id: fact.id, text: fact.text, title: fact.title, sourceTitle: fact.source.title,
        sourceUrl: safeSourceUrl(fact.source.url), checkedOn: fact.source.checkedOn };
}

export function factForDay(day) {
    const index = Math.max(0, Math.floor(Number(day) || 1) - 1) % WHISPER_FACTS.length;
    return publicFact(WHISPER_FACTS[index]);
}

export function availableDailyDay(releasedDay, completedDays = []) {
    const released = Math.max(0, Math.min(30, Math.floor(Number(releasedDay) || 0)));
    if (!released) return null;
    const completed = new Set(Array.isArray(completedDays) ? completedDays : []);
    for (let day = 1; day <= released; day += 1) if (!completed.has(day)) return day;
    return released;
}
